import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def solve(inp):
    H,W=len(inp),len(inp[0])
    sr=[r for r in range(H) if len(set(inp[r]))==1]
    sc=[c for c in range(W) if len({inp[r][c] for r in range(H)})==1]
    def segs(seps,n):
        res=[]; s=0
        for e in seps+[n]:
            if e-s>0: res.append((s,e)); s=e+1
        return res
    rb=segs(sr,H); cb=segs(sc,W)
    cnt=Counter(x for row in inp for x in row)
    sep=max(cnt,key=lambda k:sum(inp[r][c]==k for r in range(H) for c in range(W)))
    rest=[k for k in cnt if k!=sep]
    bg=max(rest,key=lambda k:cnt[k]); mb=[k for k in rest if k!=bg][0]
    colmax=[max(sum(inp[r_][cc]==mb for r_ in range(a,b)) for a,b in rb) for j,(c,d) in enumerate(cb)]
    out=[]
    for i,(a,b) in enumerate(rb):
        line=[]
        for j,(c,d) in enumerate(cb):
            n=sum(inp[r_][cc]==mb for r_ in range(a,b) for cc in range(c,d))
            v = 1 if n==colmax[j] else mb
            line.append(v if v!=mb else bg)
        out.append(line)
    return out

for key in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    try: print(key, solve(G[key+' input']))
    except Exception as e: print(key,'ERR',e)
print('test', json.dumps(solve(G['Test input'])))

